{
  "description": "The creature is a large tortoise-like reptile shown in right lateral profile standing on a small patch of dry, sparsely grassed ground. It has a high-domed shell whose lower sides and flared margins are visible as tan and dark brown scutes, four thick columnar legs heavily armored with scales ending in clawed feet, a short pointed scaly tail at the rear, and a reptilian head with a beaked mouth, dark eye, and scaly neck extended forward to the right. The entire dorsal surface of the shell is completely obscured by a dense, thick, matted mass of curly shaggy brown wool resembling a sheep's fleece that hangs down over the edges of the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "reptilian and heavily scaled with small polygonal scales, a dark eye with eyelid, a nostril near the snout tip, and a blunt beaked mouth with a slightly overhanging upper jaw",
      "where": "at the anterior end of the body on the right side of the image, extended forward on a thick neck beyond the front edge of the shell"
    },
    {
      "part": "legs",
      "looks_like": "thick, columnar and elephantine, covered in small rounded scales with larger pointed tubercles on the forelimbs",
      "where": "four legs positioned under the shell supporting the body, two on the right side fully visible in the foreground and two on the left side partially visible behind them"
    },
    {
      "part": "feet",
      "looks_like": "broad and scaly with short blunt claws/nails on the toes, the soles contacting the ground",
      "where": "at the distal end of each leg at the bottom of the image"
    },
    {
      "part": "tail",
      "looks_like": "short, tapering and pointed, armored with rounded overlapping scales",
      "where": "protruding from beneath the posterior margin of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large high-domed carapace, lower portion visible as rows of large polygonal scutes in tan, cream and dark brown with concentric growth lines and slightly flared edges, dorsal portion hidden under wool",
      "where": "covering the back and sides of the body, extending from behind the neck to above the tail"
    },
    {
      "part": "plates",
      "looks_like": "individual large scutes/plates of the shell with striped brown and cream coloration and upturned, leaf-like margins along the sides and rear",
      "where": "forming the visible lower lateral and posterior wall of the shell around the body"
    },
    {
      "part": "scales",
      "looks_like": "small polygonal, overlapping and keeled scales in gray-brown tones, larger conical pointed scales on the front of the forelimbs and smaller pebbly scales on the hind limbs, neck and head",
      "where": "covering the head, neck, legs, feet and tail"
    },
    {
      "part": "mane",
      "looks_like": "dense, thick, matted and very curly shaggy woolly fleece in mixed dark and light brown, with long curled locks hanging over the sides",
      "where": "covering the entire dorsal surface of the shell on top of the back, draping over the upper edges of the shell plates"
    }
  ],
  "attached_objects": [],
  "animals": [
    "tortoise",
    "sheep"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
